import styled from 'styled-components'
import { cores } from '../../styles'
import bgheader from '../../assets/images.nova/Vector.svg'

// Breakpoints para responsividade
const breakpoints = {
  sm: '480px',
  md: '768px',
  lg: '1024px',
  xl: '1200px'
}

export const HeaderBar = styled.header`
  background-color: ${cores.cinza};
  padding: 40px;
  height: 385px;
  display: flex;
  text-align: center;
  background-image: url(${bgheader});
  flex-direction: column; // Para empilhar os elementos verticalmente

  img {
    display: block; // Garante que a imagem será exibida como bloco
    width: 125px;
    margin: 0 auto; // Centraliza a imagem horizontalmente
  }

  div {
    display: block; // A div é um bloco, empilhando os filhos
    width: 100%;
    height: 300px;
    position: relative; // Necessário para o h1 ser posicionado em relação à div

    h1 {
      font-size: 36px;
      font-weight: 900;
      width: 539px;
      line-height: 42.2px;
      margin: 0 auto;
      position: absolute; // Posiciona o h1 de forma independente dentro da div
      bottom: -10px;
      left: 50%;
      transform: translateX(-50%);

      // Responsividade
      @media (max-width: ${breakpoints.lg}) {
        font-size: 32px;
        width: 480px;
      }

      @media (max-width: ${breakpoints.md}) {
        font-size: 28px;
        width: 420px;
      }

      @media (max-width: ${breakpoints.sm}) {
        font-size: 24px;
        width: 100%;
        line-height: 32px; // Ajuste de altura para telas pequenas
      }
    }
  }
`

export const Links = styled.ul`
  display: flex;
  margin-left: 40px;
`

export const LinkItem = styled.li`
  margin-right: 16px;
`

export const LinkCart = styled.a`
  display: flex;

  img {
    margin-left: 16px;
  }
`
